import React, { FunctionComponent } from 'react';
import Slider from 'rc-slider';
import 'rc-slider/assets/index.css';
import classNames from 'classnames';
import './index.less';

interface SliderProps {
  className?: string;
  onChange?: any;
  marks: any;
  defaultMark?: number;
  suffix: string;
  onAfterChange?: any;
  showMarks?: boolean;
  fullDots?: boolean;
}

const DistanceSlider: FunctionComponent<SliderProps> = ({
  className,
  onChange,
  marks,
  defaultMark,
  suffix,
  onAfterChange,
  showMarks,
  fullDots,
}) => {
  const distanceDisplayFormatter = (marksObj: Record<number, number>) => {
    const result = {} as any;
    Object.keys(marksObj).forEach((key: any) => {
      result[key] = `${marksObj[key]} ${suffix}`;
    });

    return result;
  };
  return (
    <div className="distance-slider-wrap">
      <Slider
        className={classNames(
          'distance-slider',
          className,
          fullDots ? 'full-dots' : undefined,
          showMarks ? undefined : 'hide-marks',
        )}
        min={1}
        max={4}
        defaultValue={defaultMark ?? 1}
        marks={distanceDisplayFormatter(marks)}
        step={null}
        dots={false}
        onChange={onChange}
        onAfterChange={onAfterChange}
      />
    </div>
  );
};

export default DistanceSlider;
